def tree_node_count(nodes: tuple) -> int:
    """统计一棵树的节点总数（列表页展示用）。"""
    total = 0
    for row in nodes:
        total += 1
        children = row[3]
        if children:
            total += tree_node_count(children)
    return total

def tree_root_question(nodes: tuple) -> str:
    """树的根问题（卡片封面句）：多根主题取第一个根。"""
    return nodes[0][2] if nodes else ""
